head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > deleteLocale]<br/>클라이언트 다국어 언어팩을 삭제합니다.",
    "validation" : [
        "Url(필수) 파라미터로 삭제할 다국어 JS 파일의 URL 을 설정할 수 있어야 합니다.",
        "WebSquare.WebSquareLang 전체가 빈 객체로 초기화되므로 해당 URL 외에 다른 경로로 로드된 다국어 데이터도 함께 제거되어야 합니다.",
    ]
}




scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (다국어 적용 버튼)
scwin.comp_init = async function () {
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        localeRef : 'websquare_name',
        useLocale : 'true',
    }

    let cList = $c.gcm.createCList(properties);

    $c.gcm.createBasicButton(cList);
}



scwin.btn_deleteLocale_onclick = function () {
    let url = par_Url.getValue();

    // 삭제 전 버튼 텍스트
    let beforeText = target1.render.textContent;
    let beforeLangKeys = Object.keys(WebSquare.WebSquareLang || {}).length;

    WebSquare.util.deleteLocale(url);

    scwin.comp_init();

    // 삭제 후 버튼 텍스트
    let afterText = target1.render.textContent;
    let afterLangKeys = Object.keys(WebSquare.WebSquareLang || {}).length;

    let result = [];
    result.push("삭제 전 텍스트: '" + beforeText + "'");
    result.push("삭제 후 텍스트: '" + afterText + "'");
    result.push("Lang 키 개수 (전: " + beforeLangKeys + ", 후: " + afterLangKeys + ")");
    result.push("다국어 삭제 : " + (afterLangKeys === 0 ? "PASS" : "FAIL"));

    wf_body_bottom.getObj("scwin").setReturnValue(result.join(", "));
}
